12	InClauseSimplificationRule::InClauseSimplificationRule(ExpressionRewriter &rewriter) : Rule(rewriter) {
13		// match on InClauseExpression that has a ConstantExpression as a check
14		auto op = make_uniq<InClauseExpressionMatcher>();
15		op->policy = SetMatcher::Policy::SOME;
16		root = std::move(op);
17	}
