19	unique_ptr<Expression> InClauseSimplificationRule::Apply(LogicalOperator &op, vector<reference<Expression>> &bindings,
20	                                                         bool &changes_made, bool is_root) {
21		auto &expr = bindings[0].get().Cast<BoundOperatorExpression>();
22		if (expr.GetChildrenMutable()[0]->GetExpressionClass() != ExpressionClass::BOUND_CAST) {
23			return nullptr;
24		}
25		auto &cast_expression = expr.GetChildrenMutable()[0]->Cast<BoundCastExpression>();
26		if (cast_expression.Child().GetExpressionClass() != ExpressionClass::BOUND_COLUMN_REF) {
27			return nullptr;
28		}
29		//! The goal here is to remove the cast from the probe expression
30		//! and apply a cast to the constant expressions. We can only do this
31		//! if the semantics do not change, which only happens when BOTH casts
32		//! are invertible.
33		auto target_type = cast_expression.source_type();
34		if (!BoundCastExpression::CastIsInvertible(target_type, cast_expression.GetReturnType())) {
35			return nullptr;
36		}
37		vector<unique_ptr<BoundConstantExpression>> cast_list;
38		//! First check if we can cast all children
39		for (size_t i = 1; i < expr.GetChildrenMutable().size(); i++) {
40			if (expr.GetChildrenMutable()[i]->GetExpressionClass() != ExpressionClass::BOUND_CONSTANT) {
41				return nullptr;
42			}
43			D_ASSERT(expr.GetChildrenMutable()[i]->IsFoldable());
44			auto constant_value = ExpressionExecutor::EvaluateScalar(GetContext(), *expr.GetChildrenMutable()[i]);
45			if (!BoundCastExpression::CastIsInvertible(constant_value.type(), target_type)) {
46				return nullptr;
47			}
48			auto new_constant = constant_value.DefaultTryCastAs(target_type);
49			if (!new_constant) {
50				return nullptr;
51			} else {
52				auto new_constant_expr = make_uniq<BoundConstantExpression>(constant_value);
53				cast_list.push_back(std::move(new_constant_expr));
54			}
55		}
56		//! We can cast, so we move the new constant
57		for (size_t i = 1; i < expr.GetChildrenMutable().size(); i++) {
58			expr.GetChildrenMutable()[i] = std::move(cast_list[i - 1]);
59	
60			//		expr->children[i] = std::move(new_constant_expr);
61		}
62		//! We can cast the full list, so we move the column
63		expr.GetChildrenMutable()[0] = std::move(cast_expression.ChildMutable());
64		return nullptr;
65	}
