67	InEnumSimplificationRule::InEnumSimplificationRule(ExpressionRewriter &rewriter) : Rule(rewriter) {
68		// match enum::VARCHAR IN (string literals)
69		auto op = make_uniq<InUniformExpressionMatcher>();
70	
71		//	Probe must be enum::VARCHAR
72		auto cast_matcher = make_uniq<CastExpressionMatcher>();
73		cast_matcher->type = make_uniq<SpecificTypeMatcher>(LogicalType::VARCHAR);
74		auto enum_matcher = make_uniq<ExpressionMatcher>();
75		enum_matcher->type = make_uniq<TypeMatcherId>(LogicalTypeId::ENUM);
76		cast_matcher->matcher = std::move(enum_matcher);
77		op->probe_matcher = std::move(cast_matcher);
78	
79		//	Children must be constant strings
80		op->child_matcher = make_uniq<ExpressionMatcher>(ExpressionClass::BOUND_CONSTANT);
81		op->child_matcher->type = make_uniq<SpecificTypeMatcher>(LogicalType::VARCHAR);
82	
83		root = std::move(op);
84	}
85	
86	unique_ptr<Expression> InEnumSimplificationRule::Apply(LogicalOperator &op, vector<reference<Expression>> &bindings,
87	                                                       bool &changes_made, bool is_root) {
88		auto &expr = bindings[0].get().Cast<BoundOperatorExpression>();
89		auto &children = expr.GetChildrenMutable();
90		auto &cast_expr = children[0]->Cast<BoundCastExpression>();
91		auto &enum_expr = cast_expr.Child();
92		auto &enum_type = enum_expr.GetReturnType();
93	
94		// Look up the domain for the original ENUM
95		string_map_t<uint64_t> enum_domain;
96		auto strings = FlatVector::GetData<string_t>(EnumType::GetValuesInsertOrder(enum_type));
97		for (uint64_t i = 0; i < EnumType::GetSize(enum_type); ++i) {
98			enum_domain[strings[i]] = i;
99		}
100	
101		vector<unique_ptr<Expression>> in_children;
102		in_children.emplace_back(enum_expr.Copy());
103	
104		for (idx_t i = 1; i < children.size(); ++i) {
105			auto &child = *children[i];
106			auto &v = child.Cast<BoundConstantExpression>().GetValue();
107			if (v.IsNull()) {
108				//	Keep NULLs
109				in_children.emplace_back(make_uniq<BoundConstantExpression>(Value(enum_type)));
110			} else {
111				auto s = v.ToString();
112				auto it = enum_domain.find(s);
113				if (it != enum_domain.end()) {
114					//	The literal is in the ENUM domain, so translate it
115					in_children.emplace_back(make_uniq<BoundConstantExpression>(Value::ENUM(it->second, enum_type)));
116				}
117				// Not in the domain, so ignore it.
118			}
119		}
120	
121		//	If ALL the children are string constants being matched against an ENUM (NOT) IN,
122		//	and SOME of them are in the domain
123		//	then swap out the children for the valid ENUM values
124		if (in_children.size() > 1) {
125			children.swap(in_children);
126		} else {
127			// constant_or_null(not_in, child[0])
128			const bool not_in = (expr.GetExpressionType() == ExpressionType::COMPARE_NOT_IN);
129			return rewriter.ConstantOrNull(in_children[0]->Copy(), Value::BOOLEAN(not_in));
130		}
131	
132		return nullptr;
133	}
