135	EnumCompareSimplificationRule::EnumCompareSimplificationRule(ExpressionRewriter &rewriter) : Rule(rewriter) {
136		// match enum::VARCHAR = string literal
137		auto op = make_uniq<ComparisonExpressionMatcher>();
138		vector<ExpressionType> types;
139		types.emplace_back(ExpressionType::COMPARE_EQUAL);
140		types.emplace_back(ExpressionType::COMPARE_NOTEQUAL);
141		types.emplace_back(ExpressionType::COMPARE_DISTINCT_FROM);
142		types.emplace_back(ExpressionType::COMPARE_NOT_DISTINCT_FROM);
143		op->expr_type = make_uniq<ManyExpressionTypeMatcher>(types);
144	
145		//	One side must be enum::VARCHAR
146		auto cast_matcher = make_uniq<CastExpressionMatcher>();
147		cast_matcher->type = make_uniq<SpecificTypeMatcher>(LogicalType::VARCHAR);
148		auto enum_matcher = make_uniq<ExpressionMatcher>();
149		enum_matcher->type = make_uniq<TypeMatcherId>(LogicalTypeId::ENUM);
150		cast_matcher->matcher = std::move(enum_matcher);
151		op->matchers.emplace_back(std::move(cast_matcher));
152	
153		//	The other must must be a constant string
154		auto const_matcher = make_uniq<ExpressionMatcher>(ExpressionClass::BOUND_CONSTANT);
155		const_matcher->type = make_uniq<SpecificTypeMatcher>(LogicalType::VARCHAR);
156		op->matchers.emplace_back(std::move(const_matcher));
157	
158		op->policy = SetMatcher::Policy::UNORDERED;
159	
160		root = std::move(op);
161	}
162	
163	unique_ptr<Expression> EnumCompareSimplificationRule::Apply(LogicalOperator &op,
164	                                                            vector<reference<Expression>> &bindings, bool &changes_made,
165	                                                            bool is_root) {
166		auto &expr = bindings[0].get().Cast<BoundFunctionExpression>();
167	
168		optional_ptr<BoundCastExpression> cast_expr;
169		optional_ptr<BoundConstantExpression> const_expr;
170		idx_t cast_idx = 0;
171		if (BoundComparisonExpression::Left(expr).GetExpressionClass() == ExpressionClass::BOUND_CONSTANT) {
172			cast_expr = BoundComparisonExpression::RightMutable(expr)->Cast<BoundCastExpression>();
173			const_expr = BoundComparisonExpression::LeftMutable(expr)->Cast<BoundConstantExpression>();
174			cast_idx = 1;
175		} else {
176			cast_expr = BoundComparisonExpression::LeftMutable(expr)->Cast<BoundCastExpression>();
177			const_expr = BoundComparisonExpression::RightMutable(expr)->Cast<BoundConstantExpression>();
178		}
179	
180		auto &enum_expr = cast_expr->Child();
181		auto &enum_type = enum_expr.GetReturnType();
182	
183		vector<unique_ptr<Expression>> cmp_children;
184		cmp_children.emplace_back(enum_expr.Copy());
185	
186		auto &v = const_expr->GetValue();
187		if (v.IsNull()) {
188			//	Keep NULLs
189			cmp_children.emplace_back(make_uniq<BoundConstantExpression>(Value(enum_type)));
190		} else {
191			// Look up the string in the domain for the original ENUM
192			const auto s = v.ToString();
193			auto strings = FlatVector::GetData<string_t>(EnumType::GetValuesInsertOrder(enum_type));
194			for (uint64_t i = 0; i < EnumType::GetSize(enum_type); ++i) {
195				if (strings[i] == s) {
196					//	The literal is in the ENUM domain, so translate it
197					cmp_children.emplace_back(make_uniq<BoundConstantExpression>(Value::ENUM(i, enum_type)));
198					if (cast_idx) {
199						// Restore the original orientation
200						std::swap(cmp_children[0], cmp_children[1]);
201					}
202					break;
203				}
204			}
205		}
206	
207		if (cmp_children.size() == 2) {
208			//	In the domain, so rewrite as enum = constant
209			BoundComparisonExpression::LeftMutable(expr) = std::move(cmp_children[0]);
210			BoundComparisonExpression::RightMutable(expr) = std::move(cmp_children[1]);
211		} else {
212			//	Not in the domain, so rewrite as ConstantOrNull(enum, ne)
213			switch (expr.GetExpressionType()) {
214			case ExpressionType::COMPARE_EQUAL:
215				return rewriter.ConstantOrNull(std::move(cmp_children[0]), Value::BOOLEAN(false));
216			case ExpressionType::COMPARE_NOT_DISTINCT_FROM:
217				return make_uniq<BoundConstantExpression>(Value::BOOLEAN(false));
218			case ExpressionType::COMPARE_NOTEQUAL:
219				return rewriter.ConstantOrNull(std::move(cmp_children[0]), Value::BOOLEAN(true));
220			case ExpressionType::COMPARE_DISTINCT_FROM:
221				return make_uniq<BoundConstantExpression>(Value::BOOLEAN(true));
222			default:
223				break;
224			}
225		}
226	
227		return nullptr;
228	}
